DC.register("MemberArchives", "<div class=\"page shell\">\n<dc-import name=\"MemberNav\" active=\"archives\" style=\"display: contents\" hint-size=\"264px,900px\"></dc-import>\n<div class=\"main\">\n<header class=\"topbar\">\n<div style=\"flex: 1 1 auto; display: flex; flex-direction: column\"><h1 class=\"display\" style=\"font-size: 24px\">Archives</h1><span class=\"small mute\">Company documents you are permitted to read and download</span></div>\n<a href=\"MemberProfile.dc.html\" style=\"display: flex; align-items: center; gap: 10px; min-height: 44px; text-decoration: none\"><span class=\"av\" aria-hidden=\"true\">SM</span><span class=\"hide-sm\" style=\"display: flex; flex-direction: column; line-height: 1.25\"><span style=\"font-weight: 600; font-size: 14.5px\">A. Sahaya Mary</span><span class=\"mono mute\" style=\"font-size: 12.5px\">SCF-0142</span></span></a>\n</header>\n\n<div class=\"content\">\n<div role=\"group\" aria-label=\"Filter by category\" style=\"display: flex; flex-wrap: wrap; gap: 8px\">\n<sc-for list=\"{{cats}}\" as=\"c\" hint-placeholder-count=\"8\">\n<button type=\"button\" class=\"{{c.cls}}\" aria-pressed=\"{{c.on}}\" onClick=\"{{c.pick}}\">{{c.label}}<span class=\"mono\" style=\"opacity: .75\">{{c.n}}</span></button>\n</sc-for>\n</div>\n\n<div class=\"toolbar\">\n<div class=\"search\" style=\"flex: 2 1 280px; max-width: 460px\">\n<svg class=\"ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14zM20 20l-3.5-3.5\"></path></svg>\n<input class=\"input\" type=\"search\" aria-label=\"Search documents by keyword\" placeholder=\"Search documents by keyword\" value=\"{{q}}\" onChange=\"{{setQ}}\">\n</div>\n<select class=\"select\" aria-label=\"Year\" value=\"{{year}}\" onChange=\"{{setYear}}\" style=\"flex: 0 1 170px\"><option value=\"all\">All years</option><option>2026</option><option>2025</option><option>2021</option></select>\n<span class=\"small mute\" aria-live=\"polite\" style=\"margin-left: auto\">{{countLabel}}</span>\n</div>\n\n<sc-if value=\"{{hasPreview}}\" hint-placeholder-val=\"{{false}}\">\n<section class=\"card\" aria-label=\"Document preview\" style=\"display: flex; flex-wrap: wrap; gap: 24px; padding: 20px; border-color: #0B5C7A; border-width: 2px\">\n<div style=\"flex: 0 1 220px; min-width: 0; padding: 14px; border-radius: 10px; background: #DDE7E9\"><img src=\"assets/doc-blue.svg\" alt=\"First page of the selected document\" style=\"width: 100%\"></div>\n<div style=\"flex: 1 1 320px; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 12px\">\n<div style=\"display: flex; flex-wrap: wrap; gap: 6px\"><span class=\"badge b-blue\">{{pv.cat}}</span><span class=\"{{pv.accessCls}}\">{{pv.access}}</span></div>\n<h2 class=\"display h-md\">{{pv.title}}</h2>\n<p class=\"body\">{{pv.desc}}</p>\n<p class=\"small mute\">{{pv.date}} · {{pv.version}} · {{pv.size}}</p>\n<div style=\"display: flex; flex-wrap: wrap; gap: 10px; margin-top: auto\">\n<button type=\"button\" class=\"btn btn-primary btn-sm\"><svg class=\"ic ic-sm\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 4v11M7 11l5 5 5-5M5 20h14\"></path></svg>Download PDF</button>\n<button type=\"button\" class=\"btn btn-ghost btn-sm\" onClick=\"{{closePreview}}\">Close preview</button>\n</div>\n</div>\n</section>\n</sc-if>\n\n<section class=\"card\" style=\"overflow: hidden\">\n<div class=\"tblbox\">\n<div class=\"t\" role=\"table\" aria-label=\"Archive documents\" style=\"min-width: 820px\">\n<div class=\"t-head\" role=\"rowgroup\"><div class=\"t-row\" role=\"row\"><span class=\"t-h\" role=\"columnheader\">Document</span><span class=\"t-h\" role=\"columnheader\">Category</span><span class=\"t-h\" role=\"columnheader\">Date</span><span class=\"t-h\" role=\"columnheader\">Version</span><span class=\"t-h\" role=\"columnheader\">Access</span><span class=\"t-h\" role=\"columnheader\"><span class=\"sr\">Actions</span></span></div></div>\n<div class=\"t-body\" role=\"rowgroup\">\n<sc-for list=\"{{rows}}\" as=\"d\" hint-placeholder-count=\"8\">\n<div class=\"t-row\" role=\"row\">\n<div class=\"t-c\" role=\"cell\"><div style=\"display: flex; gap: 12px; align-items: flex-start\"><svg class=\"ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\" style=\"color: #0B5C7A; margin-top: 2px\"><path d=\"M7 3h7l5 5v13H7zM14 3v5h5M10 13h6M10 17h6\"></path></svg><span><span style=\"font-weight: 600; font-size: 15px\">{{d.title}}</span><br><span class=\"mute\">{{d.desc}}</span></span></div></div>\n<div class=\"t-c\" role=\"cell\"><span class=\"badge b-blue\">{{d.cat}}</span></div>\n<div class=\"t-c mono\" role=\"cell\" style=\"white-space: nowrap\">{{d.date}}</div>\n<div class=\"t-c\" role=\"cell\" style=\"white-space: nowrap\">{{d.version}}</div>\n<div class=\"t-c\" role=\"cell\"><span class=\"{{d.accessCls}}\">{{d.access}}</span></div>\n<div class=\"t-c\" role=\"cell\"><div style=\"display: flex; gap: 4px; justify-content: flex-end\"><button type=\"button\" class=\"btn btn-ghost btn-sm\" onClick=\"{{d.preview}}\">Preview</button><button type=\"button\" class=\"btn-icon\" aria-label=\"{{d.aria}}\"><svg class=\"ic\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 4v11M7 11l5 5 5-5M5 20h14\"></path></svg></button></div></div>\n</div>\n</sc-for>\n</div>\n</div>\n</div>\n<sc-if value=\"{{none}}\" hint-placeholder-val=\"{{false}}\">\n<div style=\"display: flex; flex-direction: column; align-items: flex-start; gap: 10px; padding: 28px 20px\"><span style=\"font-weight: 600\">No document matches those filters.</span><button type=\"button\" class=\"btn btn-ghost btn-sm\" onClick=\"{{reset}}\">Clear filters</button></div>\n</sc-if>\n</section>\n<p class=\"small mute\">Some records are restricted. If a document you need is not listed, ask the office.</p>\n</div>\n</div>\n</div>", (function () {
class Component extends DCLogic {
constructor(props) {
super(props);
this.state = { q: '', cat: 'All', year: 'all', pv: null };
}
renderVals() {
const s = this.state;
const all = [
{ id: 'ar', title: 'Annual Report [YEAR]', desc: 'Activities, accounts summary and plans for the year.', cat: 'Annual Reports', date: '08 Oct 2026', y: '2026', version: 'Version 1', access: 'Members', size: 'PDF · [SIZE]' },
{ id: 'bm', title: 'Board meeting minutes, [MONTH YEAR]', desc: 'Minutes approved by the board.', cat: 'Meeting Records', date: '01 Oct 2026', y: '2026', version: 'Version 1', access: 'Members', size: 'PDF · [SIZE]' },
{ id: 'pl', title: 'Circular: member supply price list', desc: 'Current member prices for nets, lead weights and gear.', cat: 'Circulars', date: '24 Sep 2026', y: '2026', version: 'Version 3', access: 'Members', size: 'PDF · [SIZE]' },
{ id: 'inc', title: 'Certificate of Incorporation', desc: 'Registrar of Companies, Chennai. Also shown on the public website.', cat: 'Statutory Records', date: '28 Jul 2021', y: '2021', version: 'Original', access: 'Public', size: 'PDF · [SIZE]' },
{ id: 'moa', title: 'Memorandum of Association', desc: 'Objects for which the company was formed.', cat: 'Statutory Records', date: '[DATE]', y: '2021', version: 'Original', access: 'Public', size: 'PDF · [SIZE]' },
{ id: 'aoa', title: 'Articles of Association', desc: 'Rules by which the company is governed.', cat: 'Statutory Records', date: '[DATE]', y: '2021', version: 'Original', access: 'Public', size: 'PDF · [SIZE]' },
{ id: 'agm', title: 'AGM proceedings [YEAR]', desc: 'Record of the Annual General Meeting.', cat: 'Meeting Records', date: '[DATE]', y: '2025', version: 'Version 1', access: 'Members', size: 'PDF · [SIZE]' },
{ id: 'gp', title: 'Grievance handling policy', desc: 'How grievances are received, reviewed and closed.', cat: 'Policies', date: '[DATE]', y: '2026', version: 'Version 2', access: 'Members', size: 'PDF · [SIZE]' },
];
const names = ['All', 'Annual Reports', 'Circulars', 'Meeting Records', 'Policies', 'Historical Documents', 'Statutory Records', 'Other Records'];
const cats = names.map((label) => ({
label,
n: label === 'All' ? all.length : all.filter((d) => d.cat === label).length,
on: label === s.cat,
cls: label === s.cat ? 'chip on' : 'chip',
pick: () => this.setState({ cat: label }),
}));
const q = s.q.trim().toLowerCase();
const acc = (a) => (a === 'Public' ? 'badge b-green' : 'badge b-grey');
const rows = all.filter((d) => (s.cat === 'All' || d.cat === s.cat) && (s.year === 'all' || d.y === s.year) && (!q || (d.title + ' ' + d.desc).toLowerCase().includes(q))).map((d) => Object.assign({}, d, {
accessCls: acc(d.access),
aria: 'Download ' + d.title,
preview: () => this.setState({ pv: d.id }),
}));
const p = all.find((d) => d.id === s.pv);
return {
cats, rows,
q: s.q, year: s.year,
setQ: (e) => this.setState({ q: e.target.value }),
setYear: (e) => this.setState({ year: e.target.value }),
none: rows.length === 0,
countLabel: rows.length === 1 ? '1 document' : rows.length + ' documents',
reset: () => this.setState({ q: '', cat: 'All', year: 'all' }),
hasPreview: !!p,
pv: p ? Object.assign({}, p, { accessCls: acc(p.access) }) : {},
closePreview: () => this.setState({ pv: null }),
};
}
}
return Component;
})());

